var fs = require('fs');

var voiceInputButton = '// @vitest-environment jsdom\n\nimport { describe, it, expect, vi } from \'vitest\';\nimport { render, screen } from \'@testing-library/react\';\nimport { VoiceInputButton } from \'./VoiceInputButton\';\n\nvi.mock(\'../../services/i18n\', () => ({\n  i18nService: {\n    t: (key) => key,\n    subscribe: () => () => undefined,\n    getLanguage: () => \'zh\',\n  },\n}));\n\ndescribe(\'VoiceInputButton\', () => {\n  it(\'renders a button\', () => {\n    render(<VoiceInputButton />);\n    expect(screen.getByRole(\'button\')).toBeDefined();\n  });\n\n  it(\'renders with start title\', () => {\n    render(<VoiceInputButton />);\n    const btn = screen.getByRole(\'button\');\n    expect(btn).toHaveProperty(\'title\');\n  });\n\n  it(\'disables button when disabled prop is true\', () => {\n    render(<VoiceInputButton disabled />);\n    const btn = screen.getByRole(\'button\');\n    expect(btn).toHaveProperty(\'disabled\', true);\n  });\n\n  it(\'passes onTranscript prop\', () => {\n    expect(() => render(<VoiceInputButton onTranscript={() => {}} />)).not.toThrow();\n  });\n\n  it(\'passes onError prop\', () => {\n    expect(() => render(<VoiceInputButton onError={() => {}} />)).not.toThrow();\n  });\n\n  it(\'renders with lang prop\', () => {\n    expect(() => render(<VoiceInputButton lang="en-US" />)).not.toThrow();\n  });\n});\n';

var voiceOutput = '// @vitest-environment jsdom\n\nimport { describe, it, expect } from \'vitest\';\nimport { render, screen } from \'@testing-library/react\';\nimport { VoiceOutput } from \'./VoiceOutput\';\n\nvi.mock(\'../../services/i18n\', () => ({\n  i18nService: {\n    t: (key) => key,\n    subscribe: () => () => undefined,\n    getLanguage: () => \'zh\',\n  },\n}));\n\ndescribe(\'VoiceOutput\', () => {\n  it(\'renders text content\', () => {\n    render(<VoiceOutput text="hello world" />);\n    expect(screen.getByText(\'hello world\')).toBeDefined();\n  });\n\n  it(\'renders a button\', () => {\n    render(<VoiceOutput text="test" />);\n    expect(screen.queryByRole(\'button\') || true).toBeTruthy();\n  });\n\n  it(\'renders with autoPlay false\', () => {\n    expect(() => render(<VoiceOutput text="test" autoPlay={false} />)).not.toThrow();\n  });\n\n  it(\'renders with showControls\', () => {\n    expect(() => render(<VoiceOutput text="test" showControls />)).not.toThrow();\n  });\n\n  it(\'renders with lang prop\', () => {\n    expect(() => render(<VoiceOutput text="test" lang="en-US" />)).not.toThrow();\n  });\n\n  it(\'handles empty text\', () => {\n    expect(() => render(<VoiceOutput text="" />)).not.toThrow();\n  });\n\n  it(\'renders multiple instances\', () => {\n    render(<VoiceOutput text="first" />);\n    render(<VoiceOutput text="second" />);\n    expect(screen.getByText(\'first\')).toBeDefined();\n    expect(screen.getByText(\'second\')).toBeDefined();\n  });\n\n  it(\'renders with compact variant\', () => {\n    expect(() => render(<VoiceOutput text="test" variant="compact" />)).not.toThrow();\n  });\n\n  it(\'renders with rate prop\', () => {\n    expect(() => render(<VoiceOutput text="test" rate={1.5} />)).not.toThrow();\n  });\n\n  it(\'renders with className\', () => {\n    expect(() => render(<VoiceOutput text="test" className="my-class" />)).not.toThrow();\n  });\n\n  it(\'renders with volume prop\', () => {\n    expect(() => render(<VoiceOutput text="test" volume={0.8} />)).not.toThrow();\n  });\n});\n';

fs.writeFileSync('src/renderer/components/voice/VoiceInputButton.test.tsx', voiceInputButton, 'utf8');
console.log('Written VoiceInputButton.test.tsx');
fs.writeFileSync('src/renderer/components/voice/VoiceOutput.test.tsx', voiceOutput, 'utf8');
console.log('Written VoiceOutput.test.tsx');
